CREATE TABLE users (id TEXT PRIMARY KEY, auth_subject TEXT NOT NULL, locale TEXT NOT NULL, timezone TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE hypothesis_candidates (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, statement TEXT NOT NULL);
CREATE TABLE experiment_drafts (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,source_candidate_id TEXT NOT NULL,draft_json TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE experiments (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,draft_id TEXT NOT NULL,source_candidate_id TEXT NOT NULL,title TEXT NOT NULL,statement TEXT NOT NULL,kind TEXT NOT NULL,comparison_type TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT,ended_at TEXT,duration_days INTEGER NOT NULL,minimum_observations INTEGER NOT NULL,minimum_per_group INTEGER NOT NULL,schedule_json TEXT NOT NULL,stop_conditions_json TEXT NOT NULL,safety_notes_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE experiment_observations (id TEXT PRIMARY KEY,experiment_id TEXT NOT NULL,episode_id TEXT,idempotency_key TEXT NOT NULL DEFAULT '',observed_at TEXT NOT NULL,group_key TEXT NOT NULL,outcome REAL NOT NULL,condition_values_json TEXT NOT NULL DEFAULT '{}',source TEXT NOT NULL,eligible INTEGER NOT NULL DEFAULT 1,note TEXT,created_at TEXT NOT NULL);
CREATE TABLE experiment_evaluations (id TEXT PRIMARY KEY,experiment_id TEXT NOT NULL,evaluation_json TEXT NOT NULL,status TEXT NOT NULL,evaluated_at TEXT NOT NULL);
CREATE TABLE self_beliefs (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,statement TEXT NOT NULL,source_kind TEXT NOT NULL,status TEXT NOT NULL,user_note TEXT NOT NULL,accepted_at TEXT,last_reviewed_at TEXT,supporting_period_start TEXT,supporting_period_end TEXT,construct_key TEXT,tendency_scope TEXT,source_analysis_periods_json TEXT NOT NULL,supporting_field_pairs_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE self_belief_revisions (id TEXT PRIMARY KEY,belief_id TEXT NOT NULL,user_id TEXT NOT NULL,source_candidate_id TEXT,source_hypothesis_id TEXT,source_experiment_id TEXT,previous_statement TEXT NOT NULL,proposed_statement TEXT NOT NULL,final_statement TEXT NOT NULL,previous_construct_key TEXT,final_construct_key TEXT,resolution_action TEXT NOT NULL,user_note TEXT NOT NULL,approved_at TEXT NOT NULL,created_at TEXT NOT NULL);